def semver_sort(versions):
    def parse(v):
        # strip build metadata
        main_pre = v.split('+', 1)[0]
        if '-' in main_pre:
            main, pre = main_pre.split('-', 1)
        else:
            main, pre = main_pre, None

        parts = main.split('.')
        major, minor, patch = (int(p) for p in parts[:3])

        if pre is not None:
            ids = pre.split('.')
            id_keys = []
            for ident in ids:
                if ident.isdigit():
                    id_keys.append((0, int(ident), ''))
                else:
                    id_keys.append((1, 0, ident))
            has_pre_flag = 0  # prerelease sorts before release
            pre_key = (id_keys,)
        else:
            has_pre_flag = 1
            pre_key = ([],)

        return (major, minor, patch, has_pre_flag, pre_key)

    return sorted(versions, key=parse)

